/* Incorrect concurrent counter */
#include <stdio.h>
#include <pthread.h>
long cnt = 0;
void *counter(void *arg) {
  long i;
  for (i = 0; i < 1000000; i++)
    cnt++;
  return NULL;
}
int main (int argc, char *argv[]) {
  pthread_t t1, t2;
  pthread_create(&t1, NULL, counter, NULL);
  pthread_create(&t2, NULL, counter, NULL);
  pthread_join(t1, NULL);
  pthread_join(t2, NULL);
  printf("cnt = %ld\n", cnt);
  return 0;
}
